29	  th { text-align:left; color:var(--gold); font-size:16px; font-weight:700; padding:10px 12px; border-bottom:1px solid var(--line); white-space:nowrap; }
30	  td { padding:12px; border-bottom:1px solid rgba(255,255,255,.08); vertical-align:top; }
31	  td.name { font-weight:900; font-size:18px; white-space:nowrap; }
32	  td.phone { font-variant-numeric:tabular-nums; white-space:nowrap; }
33	  .badge { display:inline-block; background:#1c1c1c; border:1px solid var(--line); color:var(--gold);
34	           border-radius:6px; padding:2px 8px; font-size:14px; font-weight:700; }
35	  .line-yes { color:#06C755; font-weight:900; }
36	  .line-no { color:rgba(255,255,255,.35); }
37	  .empty { padding:40px 0; text-align:center; color:rgba(255,255,255,.5); font-size:18px; }
38	</style>
39	</head>
40	<body>
41	  <div class="wrap">
42	    <h1>來賓名單<span>｜大樹教練活動系統</span></h1>
43	    <p class="total">目前累計 <strong style="color:var(--gold)">{{ attendees|length }}</strong> 位來賓{% if selected %}（已篩選）{% endif %}</p>
44	
45	    <div class="events">
46	      <a class="chip {{ '' if selected else 'active' }}" href="?key={{ admin_key }}">全部來賓</a>
47	      {% for e in events %}
48	      <a class="chip {{ 'active' if selected == e.slug else '' }}" href="?key={{ admin_key }}&event={{ e.slug }}">
49	        {{ e.name }} <span class="n">{{ e.signup_count }}人</span>
50	      </a>
51	      {% endfor %}
52	    </div>
53	
54	    <a class="export" href="/admin/export.csv?key={{ admin_key }}">⬇ 下載名單（Excel 可開）</a>
55	
56	    <div class="tbl">
57	      <table>
58	        <tr><th>姓名</th><th>手機</th><th>公司／職稱</th><th>參加過的活動</th><th>首次留資料</th><th>LINE可通知</th></tr>
59	        {% for a in attendees %}
60	        <tr>
61	          <td class="name">{{ a.name }}</td>
62	          <td class="phone">{{ a.phone }}</td>
63	          <td>{{ a.company_title or '—' }}</td>
64	          <td><span class="badge">{{ a.event_count }} 場</span> {{ a.attended_events }}</td>
65	          <td>{{ a.created_at }}</td>
66	          <td>{% if a.line_bound %}<span class="line-yes">✓ 已綁定</span>{% else %}<span class="line-no">未綁定</span>{% endif %}</td>
67	        </tr>
68	        {% endfor %}
69	      </table>
70	      {% if not attendees %}<div class="empty">目前還沒有來賓資料</div>{% endif %}
71	    </div>
72	  </div>
73	</body>
74	</html>
